mkdir -p .cache
npx prettier --check "${LOCALE_FILES[@]}" > .cache/locale-prettier.log 2>&1 || true

CATALOG_AGENTS='{"catalog-fixer":{"description":"Fixes catalog formatting","prompt":"Fix only the JSON formatting problems listed in .cache/locale-prettier.log.","permissionMode":"acceptEdits"}}'

fix_catalogs() {
  claude -p "Fix the catalog formatting problems listed in .cache/locale-prettier.log" \
    --output-format json --dangerously-skip-permissions
}

summarize() {
  tail -n 200 .cache/locale-prettier.log | cline "Summarize the locale formatting failures in three bullets"
}

list_rejected() {
  claude -p "List the catalogs prettier rejected" --permission-mode dontAsk --allowedTools Read
}

review_fixes() {
  claude -p "Review the catalog fixes on this branch" --agents "$CATALOG_AGENTS"
}

case "${1:-fix}" in
  fix) fix_catalogs ;;
  summary) summarize ;;
  list) list_rejected ;;
  review) review_fixes ;;
  *) echo "usage: $0 [fix|summary|list|review]" >&2; exit 2 ;;
esac
